 function decodeBasal(buffer,meta){const d=new DataView(buffer);if(buffer.byteLength<24||String.fromCharCode(...new Uint8Array(buffer,0,4))!=='SYS1'||d.getUint32(4,true)!==1)throw Error('Неизвестный формат МРТ');const nv=d.getUint32(8,true),nf=d.getUint32(12,true),width=d.getUint32(16,true),scale=d.getUint32(20,true);if(nv!==meta.vertices||nf!==meta.triangles||width!==2||scale!==10||buffer.byteLength!==24+nv*6+nf*8)throw Error('Повреждена сетка МРТ');const pos=new Int16Array(buffer,24,nv*3),ids=new Uint16Array(buffer,24+nv*6,nf*3),parts=new Uint8Array(buffer,24+nv*6+nf*6,nf),sides=new Uint8Array(buffer,24+nv*6+nf*7,nf),smooth=new Float32Array(nv*3),faceNormals=new Float32Array(nf*3);for(let f=0;f<nf;f++){if(parts[f]<1||parts[f]>5||sides[f]>1)throw Error('Неверная МРТ-разметка');const a=ids[f*3],b=ids[f*3+1],c=ids[f*3+2];if(Math.max(a,b,c)>=nv)throw Error('Неверный индекс МРТ');const u=[0,1,2].map(j=>pos[b*3+j]-pos[a*3+j]),v=[0,1,2].map(j=>pos[c*3+j]-pos[a*3+j]),n=M.cross(u,v);faceNormals.set(M.unit(n),f*3);for(const id of[a,b,c])for(let j=0;j<3;j++)smooth[id*3+j]+=n[j];}const vertices=new Float32Array(nf*24);for(let f=0;f<nf;f++)for(let k=0;k<3;k++){const id=ids[f*3+k],p=[0,1,2].map(j=>pos[id*3+j]/scale),smoothN=M.unit([0,1,2].map(j=>smooth[id*3+j])),n=Math.hypot(...smoothN)<.5?Array.from(faceNormals.subarray(f*3,f*3+3)):smoothN;vertices.set([...p,...n,parts[f],sides[f]],f*24+k*8);}return{vertices,triangles:nf,kind:'basal',vesicles:[],meta};}
